/**
 * THE community door contract: the response shapes of the runtime's
 * `/app/communities/*` routes (authority-one-runtime src/communities/door.js,
 * `publicConfig`, `publicItem` and the route handlers).
 *
 * This is the one place the app declares what the door sends. The client
 * (communitiesClient), the feed mapper, the composer and the community agent
 * slot all read these types; none of them declares its own item or timeline
 * shape. The contract test (__tests__/doorContract.test.ts) holds these types
 * against fixtures generated by running the runtime's door
 * (__fixtures__/door/door.json, source commit noted in its `$source`).
 *
 * What the door does NOT send, and so is not here: no `role` (on items or on
 * a community), no `agentSponsor`, no `body`, no `displayName`/`avatar` on an
 * author, no `posts` key on a timeline page.
 *
 * Flag-dependent fields are optional: `is_agent`, `author`, `sources` and
 * `no_source` are present only while the runtime's community agent flag is
 * on; `agent`/`agent_error` likewise; `viewer_is_admin` only while the admin
 * role is on.
 */

/** The agent label on a community (N1): the config's agent DID. */
export type DoorCommunityAgent = {
  did: string
  /**
   * The door always sends true. Typed boolean so the JSON fixtures (whose
   * literals widen to boolean) are checked against this same type.
   */
  is_agent: boolean
}

/** A community as the door returns it (`publicConfig`). */
export type DoorCommunity = {
  id: string
  name: string
  description: string | null
  /** Header-only accent (N3: never a whole-app reskin). */
  accent: string | null
  /** The consent wording version this community requires to join. */
  wording_version: number | null
  /** Absent while the agent flag is off; null when on with no valid slot. */
  agent?: DoorCommunityAgent | null
  /** The runtime's refusal code for a misconfigured agent slot. */
  agent_error?: string
  /** The caller is a current admin. Absent while the admin role is off. */
  viewer_is_admin?: boolean
}

/**
 * An item's author (`authorOf`), from the stored author DID only. An item
 * written before the DID was stored answers `{did: null, is_agent: false}`.
 */
export type DoorItemAuthor = {
  did: string | null
  is_agent: boolean
}

/** A source an agent item cites (`normaliseSources` in agent-slot.js). */
export type DoorItemSource = {
  title: string | null
  kind: string | null
  /** A link or other reference to the cited item. */
  ref: string | null
  /** ISO date of the cited item. */
  at: string | null
}

/** One post or reply (`publicItem`). */
export type DoorItem = {
  id: string
  parentId: string | null
  /** The author's member id (an account handle), never a DID. */
  authorId: string
  text: string
  createdAt: string
  is_agent?: boolean
  author?: DoorItemAuthor
  sources?: DoorItemSource[]
  no_source?: boolean
}

/** GET /:id/timeline. Newest first; `cursor` is null on the last page. */
export type DoorTimelinePage = {
  items: DoorItem[]
  cursor: string | null
}

/** GET /app/communities */
export type DoorCommunityList = {communities: DoorCommunity[]}

/** GET /:id */
export type DoorCommunityResponse = {community: DoorCommunity}

/** GET /:id/join-info. The same body for every id. */
export type DoorJoinInfo = {wording_version: number | null}

/** POST /:id/posts and POST /:id/posts/:postId/replies */
export type DoorItemResponse = {item: DoorItem}

/** GET /:id/export */
export type DoorExport = {communityId: string; items: DoorItem[]}

/** One member of a thread (`memberRosterEntry` / `agentRosterEntry`). */
export type DoorRosterEntry = {
  id: string
  did: string | null
  is_agent: boolean
}

/** GET /:id/posts/:postId/roster */
export type DoorRoster = {postId: string; roster: DoorRosterEntry[]}

/** GET and POST /:id/agent-grant */
export type DoorAgentGrant = {communityId: string; on: boolean}

/**
 * Every key `publicItem` can send. The contract test checks fixtures against
 * this list, so a key the app starts to rely on that the door never sends
 * (`role`, `agentSponsor`, `body`) fails there rather than on a device.
 */
export const DOOR_ITEM_KEYS = [
  'id',
  'parentId',
  'authorId',
  'text',
  'createdAt',
  'is_agent',
  'author',
  'sources',
  'no_source',
] as const satisfies readonly (keyof DoorItem)[]

/**
 * Whether `v` is a door item the app can render: an object with a non-empty
 * string id, string text and string createdAt. Extra keys are tolerated here
 * (an additive runtime change must not blank the timeline); the contract
 * test is where unknown keys fail.
 */
export function isDoorItem(v: unknown): v is DoorItem {
  if (typeof v !== 'object' || v === null) return false
  const it = v as Record<string, unknown>
  return (
    typeof it.id === 'string' &&
    it.id.length > 0 &&
    typeof it.text === 'string' &&
    typeof it.createdAt === 'string'
  )
}
